"""Evaluate the saved anomaly model on an event-level CSV that is NOT generated by this project.

    python -m ml.evaluate_dataset --events path/to/events.csv [--history-days 28] [--threshold 0.5] [--out report.json]

The file needs one row per event. Required columns (aliases in brackets):
    employee_id [employee, user]   timestamp [timestamp_utc, date]   event_type   source_ip [ip, pc]
Optional columns:
    resource, outcome (success|failure|denied), records_accessed, records_downloaded, session_id, department,
    label (0/1 per event, 1 = known malicious), scenario (free text, used for per-scenario recall)

Event types must be the application's (login, login_failed, logout, resource_access, file_download, data_export,
directory_search, administrative_action, external_transfer, permission_change_attempt) and resources must be catalogue
ids (see backend/catalog.py) - map other datasets onto these first (--resource-map accepts a JSON object).

Each employee's first --history-days days form their baseline; later events are grouped into windows (by session_id;
events without one join a session starting within 30 minutes, else the calendar day) and scored with the same feature
pipeline and saved model the application uses.
A window is labelled malicious when any of its events is. Nothing is trained here: the model is only evaluated.
"""
import argparse
import csv
import json
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

import numpy as np
from sklearn.metrics import roc_auc_score

from ml.anomaly_detector import AnomalyDetector
from ml.features import EventRecord, build_baseline, extract_features

SESSIONLESS_JOIN = timedelta(minutes=30)
ALIASES = {
    "employee_id": ("employee_id", "employee", "user"),
    "timestamp": ("timestamp", "timestamp_utc", "date"),
    "event_type": ("event_type",),
    "source_ip": ("source_ip", "ip", "pc"),
}


def _column(header: list[str], name: str) -> str | None:
    lowered = {h.strip().lower(): h for h in header}
    return next((lowered[a] for a in ALIASES.get(name, (name,)) if a in lowered), None)


def _timestamp(value: str) -> datetime:
    parsed = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)


def _int(value: str | None) -> int:
    try:
        return int(float(value)) if value not in (None, "") else 0
    except ValueError:
        return 0


def load_events(path: Path, resource_map: dict[str, str] | None = None) -> dict[str, list[tuple[EventRecord, int | None, str, str]]]:
    """Group events per employee as (record, label, scenario, department)."""
    resource_map = resource_map or {}
    with path.open(newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        header = reader.fieldnames or []
        cols = {name: _column(header, name) for name in ALIASES}
        missing = [name for name, col in cols.items() if col is None]
        if missing:
            raise ValueError(f"missing required column(s): {', '.join(missing)}")
        opt = {name: _column(header, name) for name in
               ("resource", "outcome", "records_accessed", "records_downloaded", "session_id", "department", "label", "scenario")}
        grouped: dict[str, list] = defaultdict(list)
        for row in reader:
            def get(name: str) -> str:
                column = opt.get(name)
                return (row.get(column) or "").strip() if column else ""

            resource = get("resource")
            record = EventRecord(
                timestamp=_timestamp(row[cols["timestamp"]]), event_type=row[cols["event_type"]].strip(),
                source_ip=row[cols["source_ip"]].strip(), resource=resource_map.get(resource, resource) or None,
                outcome=get("outcome") or "success", records_accessed=_int(get("records_accessed")),
                records_downloaded=_int(get("records_downloaded")), session_id=get("session_id") or None,
                account=row[cols["employee_id"]].strip(),
            )
            label = get("label")
            grouped[record.account].append((record, int(float(label)) if label != "" else None, get("scenario"), get("department")))
    return grouped


def build_windows(grouped: dict, history_days: int) -> list[dict]:
    windows = []
    for employee, rows in grouped.items():
        rows.sort(key=lambda r: r[0].timestamp)
        cutoff = rows[0][0].timestamp + timedelta(days=history_days)
        history = [r[0] for r in rows if r[0].timestamp < cutoff]
        department = next((r[3] for r in rows if r[3]), "")
        baseline = build_baseline(history, home_department=department, known_ips=[], permissions={})
        by_window: dict[object, list] = defaultdict(list)
        later = [r for r in rows if r[0].timestamp >= cutoff]
        for i, (record, label, scenario, _) in enumerate(later):
            key = record.session_id
            if key is None:    # e.g. failed logins: join the session that starts within 30 minutes, else the calendar day
                key = next((n[0].session_id for n in later[i + 1:]
                            if n[0].session_id and n[0].timestamp - record.timestamp <= SESSIONLESS_JOIN), record.timestamp.date())
            by_window[key].append((record, label, scenario))
        for key, items in by_window.items():
            labels = [i[1] for i in items if i[1] is not None]
            scenarios = [i[2] for i in items if i[2]]
            windows.append({
                "employee": employee, "window": str(key), "baseline": baseline, "events": [i[0] for i in items],
                "label": max(labels) if labels else None,
                "scenario": next((s for s in scenarios if s != "normal"), scenarios[0] if scenarios else ""),
            })
    return windows


def evaluate(events_path: str | Path, *, model_path: str | Path | None = None, history_days: int = 28,
             threshold: float = 0.5, resource_map: dict[str, str] | None = None) -> dict:
    detector = AnomalyDetector(model_path)
    windows = build_windows(load_events(Path(events_path), resource_map), history_days)
    if not windows:
        raise ValueError("no events found after the baseline period; reduce --history-days or supply a longer dataset")
    results = [detector.score(extract_features(w["events"], w["baseline"])) for w in windows]
    scores = np.array([r.score for r in results])
    report: dict = {
        "model_mode": results[0].mode, "events_file": str(events_path), "history_days": history_days,
        "threshold": threshold, "n_employees": len({w["employee"] for w in windows}), "n_windows": len(windows),
        "flagged_fraction": round(float((scores >= threshold).mean()), 4),
        "score_quantiles": {q: round(float(np.quantile(scores, q)), 4) for q in (0.5, 0.9, 0.99)},
    }
    labelled = [i for i, w in enumerate(windows) if w["label"] is not None]
    labels = np.array([windows[i]["label"] for i in labelled])
    if labelled and set(labels) == {0, 1}:
        s = scores[labelled]
        report.update({
            "n_malicious_windows": int(labels.sum()), "n_normal_windows": int((labels == 0).sum()),
            "roc_auc": round(float(roc_auc_score(labels, s)), 4),
            "false_positive_rate": round(float((s[labels == 0] >= threshold).mean()), 4),
            "recall": round(float((s[labels == 1] >= threshold).mean()), 4),
        })
        by_scenario = {}
        for sc in sorted({windows[i]["scenario"] for i in labelled if windows[i]["label"] == 1 and windows[i]["scenario"]}):
            idx = [i for i in labelled if windows[i]["label"] == 1 and windows[i]["scenario"] == sc]
            by_scenario[sc] = round(float((scores[idx] >= threshold).mean()), 3)
        if by_scenario:
            report["recall_by_scenario"] = by_scenario
    else:
        report["note"] = "No label column with both classes: only the score distribution is reported."
    return report


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--events", required=True, help="event-level CSV")
    parser.add_argument("--model", help="model file (default: ML_MODEL_PATH)")
    parser.add_argument("--history-days", type=int, default=28)
    parser.add_argument("--threshold", type=float, default=0.5)
    parser.add_argument("--resource-map", help="JSON file mapping dataset resource names to catalogue ids")
    parser.add_argument("--out", help="write the JSON report here")
    args = parser.parse_args()
    mapping = json.loads(Path(args.resource_map).read_text(encoding="utf-8")) if args.resource_map else None
    result = evaluate(args.events, model_path=args.model, history_days=args.history_days, threshold=args.threshold,
                      resource_map=mapping)
    text = json.dumps(result, indent=2)
    if args.out:
        Path(args.out).write_text(text, encoding="utf-8")
    print(text)
